import json
import re
import pandas as pd
def task_func(json_str):
    """
    Load a JSON string into a dictionary, double all numerical values (including those in lists and strings),
    and create a Pandas DataFrame from the dictionary.

    Parameters:
    json_str (str): JSON string containing a flat dictionary

    Returns:
    pandas.DataFrame: DataFrame created from the dictionary with numerical values doubled

    Notes:
    - Handles flat dictionaries (no nesting)
    - Doubles numbers in: single values, lists, and strings containing numbers
    - Uses regex to extract numbers from strings
    - Returns empty DataFrame for invalid/empty input
    """
    # Handle empty or None input
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        # Parse JSON string to dictionary
        data_dict = json.loads(json_str)

        # Check if it's a dictionary
        if not isinstance(data_dict, dict):
            return pd.DataFrame()

        processed_dict = {}

        # Helper function to double numerical values
        def double_value(value):
            # If value is a number (int or float)
            if isinstance(value, (int, float)):
                return value * 2

            # If value is a string
            elif isinstance(value, str):
                # Try to extract numbers from the string using regex
                numbers = re.findall(r'-?\d+\.?\d*', value)
                if numbers:
                    # If only one number in the string, double it and return as float
                    if len(numbers) == 1:
                        return float(numbers[0]) * 2
                    # If multiple numbers, double all of them
                    else:
                        return [float(num) * 2 for num in numbers]
                # If no numbers found, return original string
                return value

            # If value is a list
            elif isinstance(value, list):
                doubled_list = []
                for item in value:
                    if isinstance(item, (int, float)):
                        doubled_list.append(item * 2)
                    elif isinstance(item, str):
                        # Try to extract number from string in list
                        numbers = re.findall(r'-?\d+\.?\d*', item)
                        if numbers:
                            if len(numbers) == 1:
                                doubled_list.append(float(numbers[0]) * 2)
                            else:
                                doubled_list.extend([float(num) * 2 for num in numbers])
                        else:
                            doubled_list.append(item)
                    else:
                        doubled_list.append(item)
                return doubled_list

            # For non-numerical types, return as-is
            else:
                return value

        # Process each key-value pair in the dictionary
        for key, value in data_dict.items():
            processed_dict[key] = double_value(value)

        # Create DataFrame from processed dictionary
        # Using pd.DataFrame([processed_dict]) to handle scalar values properly
        df = pd.DataFrame([processed_dict])

        return df

    except (json.JSONDecodeError, ValueError):
        # Return empty DataFrame for invalid JSON
        return pd.DataFrame()

