import numpy as np
from collections import defaultdict
import json
import csv
def task_func(input_file, output_file):
    """
    Read a list of dictionaries from a JSON file, calculate the mean and median for each key,
    and write the results to a CSV file.

    Args:
    input_file (str): Path to the input JSON file.
    output_file (str): Path to the output CSV file.

    Returns:
    dict: A dictionary where each key is a field from the input JSON and each value is another dictionary with the mean and median of that field.
    """
    try:
        with open(input_file, 'r') as file:
            data = json.load(file)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Error reading JSON file: {e}")

    if not isinstance(data, list):
        raise ValueError("Input JSON should contain a list of dictionaries")

    # Collect values for each key
    key_values = defaultdict(list)
    for entry in data:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in the list should be a dictionary")
        for key, value in entry.items():
            if isinstance(value, (int, float)):
                key_values[key].append(value)

    results = {}

    # Calculate mean and median for each key
    for key, values in key_values.items():
        if values:
            mean_val = np.mean(values)
            median_val = np.median(values)
            results[key] = {
                'mean': mean_val,
                'median': median_val
            }
        else:
            results[key] = {
                'mean': np.nan,
                'median': np.nan
            }

    # Write results to CSV
    with open(output_file, 'w', newline='') as csvfile:
        fieldnames = ['key', 'mean', 'median']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)

        writer.writeheader()
        for key, stats in results.items():
            writer.writerow({
                'key': key,
                'mean': stats['mean'],
                'median': stats['median']
            })

    return results

